/**
 * `int(str)` with CPython's exact grammar, returning a BigInt so that
 * arbitrary-precision arithmetic keeps working.
 */

import { PyValueError } from './errors.mjs';
import { reprString, truncateRepr } from './repr.mjs';
import { decimalValue, isPySpace } from './unicodedata.mjs';

/** CPython formats this message with `%.200R`, i.e. a 200 character cap. */
const MESSAGE_REPR_LIMIT = 200;

function invalidLiteral(text) {
  const shown = truncateRepr(reprString(text), MESSAGE_REPR_LIMIT);
  return new PyValueError(`invalid literal for int() with base 10: ${shown}`);
}

function stripPySpace(characters) {
  let start = 0;
  let end = characters.length;
  while (start < end && isPySpace(characters[start].codePointAt(0))) start += 1;
  while (end > start && isPySpace(characters[end - 1].codePointAt(0))) end -= 1;
  return characters.slice(start, end);
}

/**
 * Grammar accepted by `int(x, 10)`:
 *   whitespace* [+-]? digit (['_']? digit)* whitespace*
 * where `digit` is any Unicode decimal digit and `_` may only separate digits.
 *
 * @param {string} text
 * @returns {bigint}
 */
export function pyInt(text) {
  const characters = stripPySpace(Array.from(text));
  let index = 0;
  let negative = false;

  if (index < characters.length && (characters[index] === '+' || characters[index] === '-')) {
    negative = characters[index] === '-';
    index += 1;
  }

  let digits = '';
  let previousWasDigit = false;
  for (; index < characters.length; index += 1) {
    const character = characters[index];
    if (character === '_') {
      // An underscore must sit between two digits.
      if (!previousWasDigit) throw invalidLiteral(text);
      previousWasDigit = false;
      continue;
    }
    const value = decimalValue(character.codePointAt(0));
    if (value < 0) throw invalidLiteral(text);
    digits += String(value);
    previousWasDigit = true;
  }

  if (digits === '' || !previousWasDigit) throw invalidLiteral(text);
  const magnitude = BigInt(digits);
  return negative ? -magnitude : magnitude;
}

/**
 * `repr()` / `str()` for the handful of Python types this program prints.
 */

import { isPrintable } from './unicodedata.mjs';

const SIMPLE_ESCAPES = new Map([
  ['\\', '\\\\'],
  ['\n', '\\n'],
  ['\r', '\\r'],
  ['\t', '\\t'],
]);

function escapeUnprintable(character) {
  const codePoint = character.codePointAt(0);
  if (codePoint <= 0xff) return `\\x${codePoint.toString(16).padStart(2, '0')}`;
  if (codePoint <= 0xffff) return `\\u${codePoint.toString(16).padStart(4, '0')}`;
  return `\\U${codePoint.toString(16).padStart(8, '0')}`;
}

/** `repr()` of a `str`: single quotes unless that forces extra escaping. */
export function reprString(text) {
  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";
  let body = '';
  for (const character of text) {
    if (character === quote) {
      body += `\\${character}`;
    } else if (SIMPLE_ESCAPES.has(character)) {
      body += SIMPLE_ESCAPES.get(character);
    } else if (isPrintable(character)) {
      body += character;
    } else {
      body += escapeUnprintable(character);
    }
  }
  return `${quote}${body}${quote}`;
}

/** `repr()` of an `int`. Values are carried as BigInt for exact precision. */
export function reprInt(value) {
  return value.toString();
}

/** `repr()` of the objects `print()` receives here: `None` or a `list[int]`. */
export function reprValue(value) {
  if (value === null || value === undefined) return 'None';
  if (Array.isArray(value)) return `[${value.map(reprValue).join(', ')}]`;
  if (typeof value === 'bigint') return reprInt(value);
  if (typeof value === 'string') return reprString(value);
  return String(value);
}

/** Truncate like CPython's `%.<n>R` format code, which counts code points. */
export function truncateRepr(text, limit) {
  const characters = Array.from(text);
  if (characters.length <= limit) return text;
  return characters.slice(0, limit).join('');
}

