// usage: node gen.mjs <start> <count>   -> prints code points start..start+count-1 (skipping surrogates, NUL, and \n at edges)
const start = Number(process.argv[2]);
const count = Number(process.argv[3]);
let out = 'x';
for (let cp = start; cp < start + count && cp <= 0x10ffff; cp++) {
  if (cp === 0) continue;
  if (cp >= 0xd800 && cp <= 0xdfff) continue;
  out += String.fromCodePoint(cp);
}
out += 'x';
process.stdout.write(out);

import { execFileSync } from 'node:child_process';
import { isPrintable } from '/output/lib/python/unicodedata.mjs';

const REF = '/workspace/dataset/test14_executable';

function refRepr(value) {
  let stderr;
  try {
    execFileSync(REF, ['--a', '1', '--b', value, '--c', '5', '--d', '8'], {
      stdio: ['ignore', 'pipe', 'pipe'], encoding: 'utf8', maxBuffer: 64 * 1024 * 1024,
    });
    throw new Error('expected failure');
  } catch (e) {
    stderr = e.stderr;
  }
  const marker = "invalid int value: ";
  const i = stderr.indexOf(marker);
  if (i < 0) throw new Error('no marker: ' + JSON.stringify(stderr.slice(0, 300)));
  let rest = stderr.slice(i + marker.length);
  rest = rest.replace(/\n$/, '');
  return rest;
}

// parse a python str repr -> array of {cp, escaped}
function parseRepr(repr) {
  const quote = repr[0];
  if (repr[repr.length - 1] !== quote) throw new Error('bad quoting');
  const body = Array.from(repr.slice(1, -1));
  const out = [];
  for (let i = 0; i < body.length; i++) {
    const ch = body[i];
    if (ch !== '\\') { out.push({ cp: ch.codePointAt(0), escaped: false }); continue; }
    const n = body[i + 1];
    if (n === '\\') { out.push({ cp: 0x5c, escaped: true }); i++; }
    else if (n === 'n') { out.push({ cp: 0x0a, escaped: true }); i++; }
    else if (n === 'r') { out.push({ cp: 0x0d, escaped: true }); i++; }
    else if (n === 't') { out.push({ cp: 0x09, escaped: true }); i++; }
    else if (n === "'" || n === '"') { out.push({ cp: n.codePointAt(0), escaped: true }); i++; }
    else if (n === 'x') { out.push({ cp: parseInt(body.slice(i + 2, i + 4).join(''), 16), escaped: true }); i += 3; }
    else if (n === 'u') { out.push({ cp: parseInt(body.slice(i + 2, i + 6).join(''), 16), escaped: true }); i += 5; }
    else if (n === 'U') { out.push({ cp: parseInt(body.slice(i + 2, i + 10).join(''), 16), escaped: true }); i += 9; }
    else throw new Error('unknown escape \\' + n);
  }
  return out;
}

const start = Number(process.argv[2]);
const end = Number(process.argv[3]);
const step = Number(process.argv[4] || 8000);
const mismatches = [];
for (let base = start; base <= end; base += step) {
  const cps = [];
  for (let cp = base; cp < base + step && cp <= end; cp++) {
    if (cp === 0) continue;
    if (cp >= 0xd800 && cp <= 0xdfff) continue;
    cps.push(cp);
  }
  if (!cps.length) continue;
  const value = 'x' + cps.map((c) => String.fromCodePoint(c)).join('') + 'x';
  const parsed = parseRepr(refRepr(value));
  // strip leading/trailing 'x'
  if (parsed[0].cp !== 0x78 || parsed[parsed.length - 1].cp !== 0x78) throw new Error('sentinel lost');
  const inner = parsed.slice(1, -1);
  if (inner.length !== cps.length) {
    console.log(`LENGTH MISMATCH base=${base.toString(16)} got=${inner.length} want=${cps.length}`);
    continue;
  }
  for (let k = 0; k < cps.length; k++) {
    if (inner[k].cp !== cps[k]) { console.log(`CP MISALIGN at ${cps[k].toString(16)} got ${inner[k].cp.toString(16)}`); break; }
    const pyPrintable = !inner[k].escaped;
    const nodePrintable = isPrintable(String.fromCodePoint(cps[k]));
    if (pyPrintable !== nodePrintable) mismatches.push([cps[k], pyPrintable, nodePrintable]);
  }
}
console.log('MISMATCH COUNT', mismatches.length);
// collapse into ranges
let i = 0;
const ranges = [];
while (i < mismatches.length) {
  let j = i;
  while (j + 1 < mismatches.length && mismatches[j + 1][0] === mismatches[j][0] + 1
         && mismatches[j + 1][1] === mismatches[i][1]) j++;
  ranges.push([mismatches[i][0], mismatches[j][0], mismatches[i][1], mismatches[i][2]]);
  i = j + 1;
}
for (const [a, b, py, nd] of ranges) {
  console.log(`U+${a.toString(16).toUpperCase().padStart(4, '0')}..U+${b.toString(16).toUpperCase().padStart(4, '0')}  pyPrintable=${py} nodePrintable=${nd}  (${b - a + 1})`);
}

